def rrf(lt, st, k=60):
    s = {}
    for lst in (lt, st):
        for rank, d in enumerate(lst, 1):
            s[d] = s.get(d, 0) + 1 / (k + rank)
    return sorted(s, key=lambda d: -s[d])

def cc(lex, sem, lt, st, alpha):    # min-max over each top W, missing side = 0
    def mm(full, top):
        lo, hi = full[top].min(), full[top].max()
        return {d: (full[d] - lo) / (hi - lo) for d in top}
    L, S = mm(lex, lt), mm(sem, st)
    cand = list(dict.fromkeys([*lt, *st]))
    f = {d: alpha * S.get(d, 0) + (1 - alpha) * L.get(d, 0) for d in cand}
    return sorted(cand, key=lambda d: -f[d])

def mean_ndcg(split, fuse):
    return np.mean([ndcg10(fuse(*retrieve(q)), rel) for q, rel in qrels[split]])

